import Link from 'next/link';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { format } from 'date-fns';
import { fr } from 'date-fns/locale';
import {
  ChevronLeft, User, MapPin, Building2, Clock, CheckCircle, XCircle,
  Phone, FileText, Image as ImageIcon, Package,
  CreditCard, Loader2, AlertTriangle, MessageSquare,
  X, Archive, PenTool, Download, Upload, FileType,
} from 'lucide-react';
import { useRef } from 'react';
import { sendPush } from '@/lib/send-push';
import PhotoAnnotator from '@/components/reports/PhotoAnnotator';

interface Report {
  id: string;
  intervention_id: string;
  technician_id: string;
  text_content: string | null;
  vocal_url: string | null;
  vocal_transcription: string | null;
  photos: (string | { url: string; caption?: string; category?: string })[];
  is_billable: boolean;
  billable_reason: string | null;
  work_duration_minutes: number | null;
  supplies_text: string | null;
  is_completed: boolean;
  status: string;
  created_at: string;
  client_signature: string | null;
  pdf_url: string | null;
  docx_url: string | null;
  technician?: {
    id: string; first_name: string; last_name: string; phone: string | null;
  } | null;
  intervention?: {
    id: string; title: string; description: string | null; address: string;
    date_planned: string | null; work_order_number?: string | null;
    intervention_type: string | null;
    client_info: { name?: string; phone?: string } | null;
    regie?: { id: string; name: string } | null;
  } | null;
}

export default function ValidateReportDetailPage() {
  const router = useRouter();
  const params = useParams();
  const reportId = params.id as string;

  const [report, setReport] = useState<Report | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isValidating, setIsValidating] = useState(false);
  const [isRejecting, setIsRejecting] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState(false);
  const [rejectReason, setRejectReason] = useState('');
  const [selectedPhoto, setSelectedPhoto] = useState<string | null>(null);
  const [showAnnotator, setShowAnnotator] = useState(false);
  const [isUploadingDocx, setIsUploadingDocx] = useState(false);
  const docxInputRef = useRef<HTMLInputElement>(null);
  // Editable fields for secretary
  const [editTextContent, setEditTextContent] = useState('');
  const [editSuppliesText, setEditSuppliesText] = useState('');
  const [editWorkDuration, setEditWorkDuration] = useState<number>(0);
  const [revisionMessage, setRevisionMessage] = useState('');

  const supabase = createClient();

  useEffect(() => {
    const fetchReport = async () => {
      setIsLoading(true);
      const { data, error } = await supabase
        .from('reports')
        .select(`
          *, technician:users!reports_technician_id_fkey(id, first_name, last_name, phone),
          intervention:interventions(id, title, description, address, date_planned, work_order_number, intervention_type, client_info, regie:regies(id, name))
        `)
        .eq('id', reportId)
        .single();

      if (error) {
        console.error('Erreur fetch rapport:', error);
        toast.error('Erreur lors du chargement du rapport');
        router.push('/reports/validate');
        return;
      }
      if (!data) {
        toast.error('Rapport introuvable');
        router.push('/reports/validate');
        return;
      }
      const r = data as Report;
      setReport(r);
      setEditTextContent(r.text_content || '');
      setEditSuppliesText(r.supplies_text || '');
      setEditWorkDuration(r.work_duration_minutes || 0);
      setIsLoading(false);
    };
    fetchReport();
  }, [reportId, router, supabase]);

  const handleValidate = async () => {
    if (!report) return;
    setIsValidating(true);
    try {
      // ÉTAPE 0: SAUVEGARDER LES MODIFICATIONS DE LA SECRÉTAIRE
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { error: saveError } = await (supabase as any)
        .from('reports')
        .update({
          text_content: editTextContent || null,
          supplies_text: editSuppliesText || null,
          work_duration_minutes: editWorkDuration || null,
          vocal_transcription: null,
        })
        .eq('id', report.id);
      if (saveError) throw saveError;

      // ÉTAPE 1: GÉNÉRER LE PDF RAPPORT (skip si un Word édité a déjà été uploadé)
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const hasCustomDocx = Boolean((report as any).docx_url);
      if (!hasCustomDocx) {
        try {
          const pdfResponse = await fetch(
            process.env.NEXT_PUBLIC_N8N_REPORT_PDF_WEBHOOK || '',
            {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ report_id: report.id }),
            }
          );
          if (pdfResponse.ok) {
            await pdfResponse.json();
          }
        } catch {
          // PDF generation is non-blocking
        }
      }

      // ÉTAPE 2: VALIDER LE RAPPORT
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { error: reportError } = await (supabase as any)
        .from('reports')
        .update({ status: 'validated', validated_at: new Date().toISOString() })
        .eq('id', report.id);
      if (reportError) throw reportError;

      // ÉTAPE 3: INTERVENTION (seulement si facturable)
      if (!report.intervention_id) {
        throw new Error('intervention_id manquant sur le rapport');
      }
      if (report.is_billable) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { error: interventionError } = await (supabase as any)
          .from('interventions')
          .update({ status: 'ready_to_bill' })
          .eq('id', report.intervention_id);
        if (interventionError) throw interventionError;
      } else {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { error: interventionError } = await (supabase as any)
          .from('interventions')
          .update({ status: 'archived' })
          .eq('id', report.intervention_id);
        if (interventionError) throw interventionError;
      }

      // ÉTAPE 4: REDIRECTION
      toast.success('Rapport validé ! PDF généré et prêt à facturer. 🎉');
      router.push('/reports/history');
      router.refresh();
    } catch (error) {
      console.error('[VALIDATE ERROR]', error);
      toast.error('Erreur lors de la validation.');
    } finally {
      setIsValidating(false);
    }
  };

  const handleReject = async () => {
    if (!report || !rejectReason.trim()) { toast.error('Veuillez indiquer une raison'); return; }
    setIsRejecting(true);
    try {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { error } = await (supabase as any)
        .from('reports').update({
          status: 'rejected',
          revision_requested: true,
          revision_message: rejectReason,
        }).eq('id', report.id).select('id').single();
      if (error) throw error;

      // Notify the technician
      if (report.technician_id) {
        const { data: { user: currentUser } } = await supabase.auth.getUser();
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { error: notificationError } = await (supabase as any).from('notifications').insert({
          recipient_id: report.technician_id,
          sender_id: currentUser?.id || null,
          title: 'Rapport rejeté',
          message: `Motif : ${rejectReason}`,
          type: 'revision_requested',
          reference_id: report.id,
          reference_type: 'report',
        });
        if (notificationError) throw new Error('Retour enregistré, mais notification non envoyée.');
        sendPush({
          recipient_id: report.technician_id,
          title: 'Rapport rejeté',
          message: `Motif : ${rejectReason}`,
          url: technicianReportLink(report.intervention_id || '', report.id),
        });
      }

      toast.success('Rapport rejeté — technicien notifié');
      setShowRejectModal(false);
      router.push('/reports/validate');
      router.refresh();
    } catch (error) {
      console.error('Rejection error:', error);
      toast.error(error instanceof Error ? error.message : 'Impossible d’envoyer le retour.');
    } finally {
      setIsRejecting(false);
    }
  };

  const handleAnnotationSave = async (newUrl: string) => {
    if (!report || !selectedPhoto) return;
    // Replace the photo in the report's photos array
    const updatedPhotos = report.photos.map((photo) => {
      if (typeof photo === 'string') {
        const fullUrl = getPhotoUrl(photo);
        if (fullUrl === selectedPhoto || photo === selectedPhoto) {
          return newUrl;
        }
        return photo;
      }
      const fullUrl = getPhotoUrl(photo.url);
      if (fullUrl === selectedPhoto || photo.url === selectedPhoto) {
        return { ...photo, url: newUrl };
      }
      return photo;
    });

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { error } = await (supabase as any)
      .from('reports')
      .update({ photos: updatedPhotos })
      .eq('id', report.id);

    if (error) {
      console.error('Erreur mise à jour photos:', error);
      toast.error('Erreur lors de la mise à jour de la photo');
    } else {
      setReport({ ...report, photos: updatedPhotos });
    }
    setShowAnnotator(false);
    setSelectedPhoto(null);
  };

  const handleDocxUpload = async (file: File) => {
    if (!report) return;
    setIsUploadingDocx(true);
    try {
      const fd = new FormData();
      fd.append('file', file);
      const res = await fetch(`/api/reports/${report.id}/docx`, {
        method: 'POST',
        body: fd,
      });
      const json = await res.json();
      if (!res.ok) {
        throw new Error(json.detail || json.error || 'Conversion échouée');
      }
      toast.success('Word importé et PDF mis à jour ✅');
      setReport({ ...report, pdf_url: json.pdf_url, docx_url: json.docx_url });
    } catch (e) {
      console.error('Upload Word error', e);
      toast.error(`Erreur upload Word: ${(e as Error).message}`);
    } finally {
      setIsUploadingDocx(false);
      if (docxInputRef.current) docxInputRef.current.value = '';
    }
  };

  // Helper used before report is loaded — declared as function for hoisting
  function getPhotoUrl(path: string): string {
    if (!path) return '';
    if (path.startsWith('http') || privateReportPhotoPath(path)) return path;
    return `${process.env.NEXT_PUBLIC_SUPABASE_URL}/storage/v1/object/public/photos/${path}`;
  }

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-center">
          <Loader2 className="w-10 h-10 text-blue-600 animate-spin mx-auto mb-3" />
          <p className="text-gray-500">Chargement du rapport...</p>
        </div>
      </div>
    );
  }

  if (!report) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <p className="text-gray-500">Rapport introuvable</p>
      </div>
    );
  }

  const intervention = report.intervention;
  const technician = report.technician;
  const clientInfo = intervention?.client_info as { name?: string; phone?: string } | null;

  const rawPhotos = report.photos || [];
  const photosBefore: { url: string; caption?: string }[] = [];
  const photosAfter: { url: string; caption?: string }[] = [];
  const photosUncategorized: { url: string; caption?: string }[] = [];

  rawPhotos.forEach((photo) => {
    if (typeof photo === 'string') {
      photosUncategorized.push({ url: getPhotoUrl(photo) });
    } else if (photo.category === 'before') {
      photosBefore.push({ url: getPhotoUrl(photo.url), caption: photo.caption });
    } else if (photo.category === 'after') {
      photosAfter.push({ url: getPhotoUrl(photo.url), caption: photo.caption });
    } else {
      photosUncategorized.push({ url: getPhotoUrl(photo.url), caption: photo.caption });
    }
  });

  const hasCategories = photosBefore.length > 0 || photosAfter.length > 0;
  const allPhotosBefore = hasCategories ? photosBefore : photosUncategorized;
  const allPhotosAfter = hasCategories ? photosAfter : [];

  const hourlyRate = 110;

  const handlePhotoClick = (url: string) => {
    setSelectedPhoto(url);
    if (report.status !== 'validated') {
      setShowAnnotator(true);
    }
  };

  const PhotoGallery = ({ photos, title, emptyText }: { photos: { url: string; caption?: string }[]; title: string; emptyText: string }) => (
    <div>
      <h3 className="text-sm font-medium text-gray-700 mb-3">{title}</h3>
      {photos.length > 0 ? (
        <div className="grid grid-cols-2 gap-3">
          {photos.map((photo, index) => (
            <button key={index} onClick={() => handlePhotoClick(photo.url)} className="relative aspect-square rounded-xl overflow-hidden bg-gray-100 group">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img src={photo.url} alt={photo.caption || `Photo ${index + 1}`} className="w-full h-full object-cover" onError={(e) => { e.currentTarget.style.display = 'none'; }} />
              <div className="absolute inset-0 bg-black/0 group-hover:bg-black/30 transition-colors flex items-center justify-center">
                <PenTool className="w-6 h-6 text-white opacity-0 group-hover:opacity-100 transition-opacity drop-shadow-lg" />
                <span className="absolute bottom-2 left-0 right-0 text-xs text-white opacity-0 group-hover:opacity-100 transition-opacity drop-shadow-lg font-medium">Annoter</span>
              </div>
            </button>
          ))}
        </div>
      ) : (
        <p className="text-sm text-gray-400 italic py-4 text-center">{emptyText}</p>
      )}
    </div>
  );

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Link href={report.status === 'validated' ? '/reports/history' : '/reports/validate'} className="p-2 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded-lg transition-colors">
            <ChevronLeft className="w-5 h-5" />
          </Link>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-xl font-bold text-gray-900">{intervention?.title || "Rapport d'intervention"}</h1>
              {intervention?.work_order_number && (
                <span className="px-2.5 py-1 rounded-lg text-sm font-bold bg-amber-100 text-amber-800 border border-amber-200">Bon N° {intervention.work_order_number}</span>
              )}
            </div>
            <p className="text-sm text-gray-500">Soumis le {format(new Date(report.created_at), "d MMMM yyyy 'à' HH:mm", { locale: fr })}</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {/* Statut Terminée */}
          {report.is_completed === false && (
            <span className="px-2.5 py-1.5 rounded-lg text-xs font-bold bg-amber-100 text-amber-700 border border-amber-200">⚠️ NON TERMINÉE</span>
          )}
          {!report.is_billable && (
            <span className="px-2.5 py-1.5 rounded-lg text-xs font-bold bg-gray-200 text-gray-600">NON FACTURABLE</span>
          )}
          <span className={`px-3 py-1.5 rounded-lg text-sm font-medium ${report.status === 'submitted' ? 'bg-blue-100 text-blue-700' : report.status === 'validated' ? 'bg-emerald-100 text-emerald-700' : report.status === 'rejected' ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'}`}>
            {report.status === 'submitted' ? 'À valider' : report.status === 'validated' ? '✓ Validé' : report.status === 'rejected' ? '⚠️ Rejeté' : report.status === 'draft' ? 'Brouillon' : report.status}
          </span>
        </div>
      </div>

      {/* Warning si non terminée */}
      {report.is_completed === false && (
        <div className="bg-amber-50 border border-amber-200 rounded-2xl p-4 flex items-start gap-3">
          <AlertTriangle className="w-5 h-5 text-amber-600 mt-0.5 flex-shrink-0" />
          <div>
            <p className="font-semibold text-amber-800">Intervention non terminée</p>
            <p className="text-sm text-amber-600">Le technicien a indiqué que l&apos;intervention n&apos;est pas terminée. Un retour sur place sera probablement nécessaire.</p>
          </div>
        </div>
      )}

      {/* Export Banner — PDF + Word + Upload édité */}
      <div className="bg-gradient-to-r from-slate-50 to-blue-50 border border-slate-200 rounded-2xl p-4 flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center">
            <FileText className="w-5 h-5 text-blue-700" />
          </div>
          <div>
            <p className="font-semibold text-gray-900">Exporter le rapport</p>
            <p className="text-sm text-gray-500">
              Télécharge en Word pour éditer, puis remonte le fichier pour mettre à jour le PDF.
            </p>
          </div>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          {report.pdf_url && (
            <a
              href={report.pdf_url}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center gap-2 py-2.5 px-4 bg-red-600 text-white rounded-xl font-semibold hover:bg-red-700 transition-all active:scale-[0.98] shadow-md shadow-red-600/20"
            >
              <Download className="w-4 h-4" /> PDF
            </a>
          )}
          <a
            href={`/api/reports/${report.id}/docx`}
            className="inline-flex items-center gap-2 py-2.5 px-4 bg-blue-600 text-white rounded-xl font-semibold hover:bg-blue-700 transition-all active:scale-[0.98] shadow-md shadow-blue-600/20"
          >
            <FileType className="w-4 h-4" /> Word
          </a>
          <input
            ref={docxInputRef}
            type="file"
            accept=".docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document"
            className="hidden"
            onChange={(e) => {
              const f = e.target.files?.[0];
              if (f) handleDocxUpload(f);
            }}
          />
          <button
            onClick={() => docxInputRef.current?.click()}
            disabled={isUploadingDocx}
            className="inline-flex items-center gap-2 py-2.5 px-4 bg-white border-2 border-blue-200 text-blue-700 rounded-xl font-semibold hover:bg-blue-50 disabled:opacity-50 transition-all"
          >
            {isUploadingDocx ? <Loader2 className="w-4 h-4 animate-spin" /> : <Upload className="w-4 h-4" />}
            {isUploadingDocx ? 'Conversion…' : 'Importer Word édité'}
          </button>
        </div>
      </div>

      {/* 2 columns */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* LEFT COLUMN */}
        <div className="space-y-6">
          {/* Intervention Info */}
          <div className="bg-white rounded-2xl border border-gray-200 p-6 shadow-sm">
            <h2 className="font-semibold text-gray-900 mb-4 flex items-center gap-2"><FileText className="w-5 h-5 text-blue-600" />Informations intervention</h2>
            <div className="space-y-4">
              {technician && (<div className="flex items-start gap-3"><User className="w-5 h-5 text-gray-400 mt-0.5" /><div><p className="text-sm text-gray-500">Technicien</p><p className="font-medium text-gray-900">{technician.first_name} {technician.last_name}</p>{technician.phone && (<a href={`tel:${technician.phone}`} className="text-sm text-blue-600">{technician.phone}</a>)}</div></div>)}
              {intervention?.regie && (<div className="flex items-start gap-3"><Building2 className="w-5 h-5 text-gray-400 mt-0.5" /><div><p className="text-sm text-gray-500">Régie</p><p className="font-medium text-gray-900">{intervention.regie.name}</p></div></div>)}
              {intervention?.address && (<div className="flex items-start gap-3"><MapPin className="w-5 h-5 text-gray-400 mt-0.5" /><div><p className="text-sm text-gray-500">Adresse</p><p className="font-medium text-gray-900">{intervention.address}</p></div></div>)}
              {clientInfo?.name && (<div className="flex items-start gap-3"><Phone className="w-5 h-5 text-gray-400 mt-0.5" /><div><p className="text-sm text-gray-500">Client</p><p className="font-medium text-gray-900">{clientInfo.name}</p>{clientInfo.phone && (<a href={`tel:${clientInfo.phone}`} className="text-sm text-blue-600">{clientInfo.phone}</a>)}</div></div>)}
              {intervention?.date_planned && (<div className="flex items-start gap-3"><Clock className="w-5 h-5 text-gray-400 mt-0.5" /><div><p className="text-sm text-gray-500">Date planifiée</p><p className="font-medium text-gray-900">{format(new Date(intervention.date_planned), "EEEE d MMMM yyyy 'à' HH:mm", { locale: fr })}</p></div></div>)}
            </div>
          </div>

          {/* Description */}
          <div className="bg-white rounded-2xl border border-gray-200 p-6 shadow-sm">
            <h2 className="font-semibold text-gray-900 mb-4 flex items-center gap-2"><MessageSquare className="w-5 h-5 text-blue-600" />Description du travail</h2>
            <textarea
              value={editTextContent}
              onChange={(e) => setEditTextContent(e.target.value)}
              placeholder="Aucune description fournie"
              rows={5}
              className="w-full px-4 py-3 bg-blue-50/50 border-2 border-blue-200 rounded-xl text-gray-700 focus:outline-none focus:ring-2 focus:ring-blue-400 focus:border-blue-400 resize-y"
            />
          </div>

          {/* Fournitures (texte libre) */}
          <div className="bg-white rounded-2xl border border-gray-200 p-6 shadow-sm">
            <h2 className="font-semibold text-gray-900 mb-4 flex items-center gap-2"><Package className="w-5 h-5 text-amber-600" />Fournitures utilisées</h2>
            <textarea
              value={editSuppliesText}
              onChange={(e) => setEditSuppliesText(e.target.value)}
              placeholder="Aucune fourniture notée"
              rows={4}
              className="w-full px-4 py-3 bg-blue-50/50 border-2 border-blue-200 rounded-xl text-gray-700 focus:outline-none focus:ring-2 focus:ring-blue-400 focus:border-blue-400 resize-y"
            />
            <p className="text-xs text-gray-400 mt-3">💡 Les prix des fournitures seront ajoutés lors de la facturation dans Bexio</p>
          </div>
        </div>

        {/* RIGHT COLUMN */}
        <div className="space-y-6">
          {/* Photos Before */}
          <div className="bg-white rounded-2xl border border-gray-200 p-6 shadow-sm">
            <h2 className="font-semibold text-gray-900 mb-4 flex items-center gap-2">
              <ImageIcon className="w-5 h-5 text-orange-500" />Photos avant ({allPhotosBefore.length})
            </h2>
            <PhotoGallery photos={allPhotosBefore} title="État initial / Problème constaté" emptyText="Aucune photo avant" />
          </div>

          {/* Photos After */}
          <div className="bg-white rounded-2xl border border-gray-200 p-6 shadow-sm">
            <h2 className="font-semibold text-gray-900 mb-4 flex items-center gap-2">
              <ImageIcon className="w-5 h-5 text-emerald-500" />Photos après ({allPhotosAfter.length})
            </h2>
            <PhotoGallery photos={allPhotosAfter} title="Travail réalisé / Résultat final" emptyText="Aucune photo après" />
          </div>

          {/* Client Signature */}
          <div className="bg-white rounded-2xl border border-gray-200 p-6 shadow-sm">
            <h2 className="font-semibold text-gray-900 mb-4 flex items-center gap-2">
              <PenTool className="w-5 h-5 text-indigo-600" />Signature du client
            </h2>
            {report.client_signature ? (
              <div className="border border-gray-200 rounded-xl overflow-hidden bg-white p-2">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={report.client_signature} alt="Signature du client" className="w-full h-auto max-h-48 object-contain" onError={(e) => { e.currentTarget.style.display = 'none'; }} />
              </div>
            ) : (
              <div className="text-center py-8 border-2 border-dashed border-gray-200 rounded-xl">
                <PenTool className="w-10 h-10 text-gray-300 mx-auto mb-2" />
                <p className="text-gray-400 italic">Aucune signature</p>
              </div>
            )}
          </div>

          {/* Récapitulatif */}
          <div className="bg-white rounded-2xl border border-gray-200 p-6 shadow-sm">
            <h2 className="font-semibold text-gray-900 mb-4 flex items-center gap-2"><CreditCard className="w-5 h-5 text-emerald-600" />Récapitulatif</h2>
            <div className="space-y-4">
              {/* Durée (masqué pour chantiers) */}
              {report.intervention?.intervention_type !== 'chantier' && (
              <div className="flex items-center justify-between p-4 bg-blue-50/50 border-2 border-blue-200 rounded-xl">
                <div className="flex items-center gap-3">
                  <Clock className="w-5 h-5 text-blue-500" />
                  <div>
                    <p className="font-medium text-gray-900">Temps de travail</p>
                    <p className="text-sm text-gray-500">{hourlyRate} CHF/heure</p>
                  </div>
                </div>
                <div className="text-right flex items-baseline gap-2">
                  <input
                    type="number"
                    min={0}
                    step={15}
                    value={editWorkDuration}
                    onChange={(e) => setEditWorkDuration(Number(e.target.value))}
                    className="w-20 text-right text-2xl font-bold text-gray-900 bg-white border-2 border-blue-200 rounded-lg px-2 py-1 focus:outline-none focus:ring-2 focus:ring-blue-400 focus:border-blue-400"
                  />
                  <span className="text-lg font-semibold text-gray-600">min</span>
                  <p className="text-sm text-gray-500 ml-2">≈ {((editWorkDuration / 60) * hourlyRate).toFixed(2)} CHF</p>
                </div>
              </div>
              )}

              {/* Terminée */}
              <div className={`p-4 rounded-xl ${report.is_completed !== false ? 'bg-emerald-50' : 'bg-amber-50'}`}>
                <div className="flex items-center gap-3">
                  {report.is_completed !== false ? <CheckCircle className="w-5 h-5 text-emerald-500" /> : <XCircle className="w-5 h-5 text-amber-500" />}
                  <p className={`font-medium ${report.is_completed !== false ? 'text-emerald-800' : 'text-amber-800'}`}>
                    {report.is_completed !== false ? 'Intervention terminée' : 'Intervention non terminée'}
                  </p>
                </div>
              </div>

              {/* Facturable */}
              <div className={`p-4 rounded-xl ${report.is_billable ? 'bg-emerald-50' : 'bg-amber-50'}`}>
                <div className="flex items-start gap-3">
                  {report.is_billable ? <CheckCircle className="w-5 h-5 text-emerald-500 mt-0.5" /> : <AlertTriangle className="w-5 h-5 text-amber-500 mt-0.5" />}
                  <div>
                    <p className={`font-medium ${report.is_billable ? 'text-emerald-800' : 'text-amber-800'}`}>{report.is_billable ? 'Intervention facturable' : 'Non facturable'}</p>
                    {!report.is_billable && report.billable_reason && (<p className="text-sm text-amber-600 mt-1">Raison : {report.billable_reason}</p>)}
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Actions */}
          <div className="bg-white rounded-2xl border border-gray-200 p-6 shadow-sm lg:sticky lg:top-6">
            <h2 className="font-semibold text-gray-900 mb-4">Actions</h2>
            <div className="space-y-3">
              <button onClick={handleValidate} disabled={isValidating || report.status === 'validated'}
                className={`w-full flex items-center justify-center gap-2 py-4 px-6 text-white rounded-xl font-semibold disabled:opacity-50 disabled:cursor-not-allowed transition-all active:scale-[0.98] shadow-lg ${report.is_billable ? 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-600/30' : 'bg-gray-600 hover:bg-gray-700 shadow-gray-600/30'}`}>
                {isValidating ? (<><Loader2 className="w-5 h-5 animate-spin" />Validation en cours...</>) : report.is_billable ? (<><CheckCircle className="w-5 h-5" />Valider &amp; Prêt pour facturation</>) : (<><Archive className="w-5 h-5" />Valider &amp; Archiver (non facturable)</>)}
              </button>
              <button onClick={() => setShowRejectModal(true)} disabled={isValidating || report.status === 'validated'}
                className="w-full flex items-center justify-center gap-2 py-4 px-6 bg-white border-2 border-red-200 text-red-600 rounded-xl font-semibold hover:bg-red-50 disabled:opacity-50 disabled:cursor-not-allowed transition-all active:scale-[0.98]">
                <MessageSquare className="w-5 h-5" />Demander des informations
              </button>
            </div>
            {report.status === 'validated' && (<p className="text-sm text-emerald-600 text-center mt-4">✓ Ce rapport a déjà été validé</p>)}
          </div>
        </div>
      </div>

      {/* Photo Annotator */}
      {selectedPhoto && showAnnotator && report.status !== 'validated' && (
        <PhotoAnnotator
          photoUrl={selectedPhoto}
          onSave={handleAnnotationSave}
          onCancel={() => { setShowAnnotator(false); setSelectedPhoto(null); }}
          storagePath={`reports/${report.id}`}
        />
      )}

      {/* Photo Lightbox (for validated reports or fallback) */}
      {selectedPhoto && !showAnnotator && (
        <div className="fixed inset-0 z-50 bg-black/90 flex items-center justify-center p-4" onClick={() => setSelectedPhoto(null)}>
          <button onClick={() => setSelectedPhoto(null)} className="absolute top-4 right-4 p-2 bg-white/10 hover:bg-white/20 rounded-full transition-colors">
            <X className="w-6 h-6 text-white" />
          </button>
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src={selectedPhoto} alt="Photo agrandie" className="max-w-full max-h-full object-contain rounded-lg" onClick={(e) => e.stopPropagation()} onError={(e) => { e.currentTarget.style.display = 'none'; }} />
        </div>
      )}

      {/* Reject Modal */}
      {showRejectModal && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl max-w-md w-full p-6" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-start justify-between mb-4">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-amber-100 rounded-full flex items-center justify-center"><AlertTriangle className="w-5 h-5 text-amber-600" /></div>
                <div><h3 className="font-semibold text-gray-900">Demander des informations</h3><p className="text-sm text-gray-500">Le technicien sera notifié</p></div>
              </div>
              <button onClick={() => setShowRejectModal(false)} className="p-1 text-gray-400 hover:text-gray-600"><X className="w-5 h-5" /></button>
            </div>
            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-2">Qu&apos;est-ce qui manque ou doit être corrigé ?</label>
              <textarea value={rejectReason} onChange={(e) => setRejectReason(e.target.value)} placeholder="Ex: Merci d'ajouter des photos avant/après..." className="w-full h-32 px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-amber-500 resize-none" />
            </div>
            <div className="flex gap-3">
              <button onClick={() => setShowRejectModal(false)} className="flex-1 py-2.5 px-4 border border-gray-200 text-gray-700 rounded-lg font-medium hover:bg-gray-50 transition-colors">Annuler</button>
              <button onClick={handleReject} disabled={isRejecting || !rejectReason.trim()} className="flex-1 py-2.5 px-4 bg-amber-600 text-white rounded-lg font-medium hover:bg-amber-700 disabled:opacity-50 transition-colors flex items-center justify-center gap-2">
                {isRejecting ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Envoyer'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { ChantierDocuments } from '@/components/documents/ChantierDocuments';

import { useState, useEffect, useCallback } from 'react';
import { useParams, useRouter } from 'next/navigation';
import {
  ChevronLeft,
  MapPin,
  Phone,
  Mail,
  Building2,
  Key,
  MessageSquare,
  Send,
  Loader2,
  HardHat,
  User,
  AlertTriangle,
  Droplets,
  Zap,
  Flame,
  FileText,
  Camera,
  Plus,
  X,
  Image as ImageIcon,
  Bell,
  CalendarDays,
} from 'lucide-react';
import { createClient } from '@/lib/supabase/client';
import type { Report, User as UserRow } from '@/types/database';
import { normalizeImage } from '@/lib/normalize-image';
import { sendPush } from '@/lib/send-push';
import { computeChantierProgress } from '@/lib/chantier-progress';
import { toast } from 'sonner';
import { format } from 'date-fns';
import { fr } from 'date-fns/locale';
import Link from 'next/link';

// ─── Types ───────────────────────────────────────────────────────────────────

interface ChantierIntervention {
  id: string;
  title: string;
  description: string | null;
  address: string;
  date_planned: string | null;
  date_end: string | null;
  status: string;
  client_info: { name?: string; phone?: string; email?: string } | null;
  keys_info: string | null;
  regie?: { id: string; name: string; phone?: string; email_contact?: string } | null;
}

interface ChantierDetails {
  id: string;
  intervention_id: string;
  architect_name: string | null;
  architect_phone: string | null;
  architect_email: string | null;
  site_manager_name: string | null;
  site_manager_phone: string | null;
  keys_location: string | null;
  access_notes: string | null;
  progress_percent: number;
}

interface ChantierMessage {
  id: string;
  message: string;
  photos: string[] | null;
  created_at: string;
  author?: { id: string; first_name: string; last_name: string } | null;
}

interface CutoffNotice {
  id: string;
  cutoff_type: string;
  start_date: string;
  end_date_estimated: string | null;
  floors_affected: string | null;
  message: string | null;
  created_at: string;
}

interface ChantierPhoto {
  id: string;
  photo_url: string;
  caption: string | null;
  created_at: string;
  user?: { id: string; first_name: string; last_name: string } | null;
}

interface InterventionReminder {
  id: string;
  reminder_date: string;
  message: string;
  completed: boolean;
  reminder_type: string | null;
  created_at: string;
}

type TabType = 'overview' | 'journal' | 'cutoffs' | 'photos';

// ─── Component ───────────────────────────────────────────────────────────────

export default function ChantierDetailPage() {
  const params = useParams();
  const router = useRouter();
  const interventionId = params.id as string;
  const supabase = createClient();

  const [intervention, setIntervention] = useState<ChantierIntervention | null>(null);
  const [details, setDetails] = useState<ChantierDetails | null>(null);
  const [messages, setMessages] = useState<ChantierMessage[]>([]);
  const [cutoffs, setCutoffs] = useState<CutoffNotice[]>([]);
  const [chantierPhotos, setChantierPhotos] = useState<ChantierPhoto[]>([]);
  const [reminders, setReminders] = useState<InterventionReminder[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<TabType>('overview');

  // Journal form
  const [newMessage, setNewMessage] = useState('');
  const [isSendingMessage, setIsSendingMessage] = useState(false);

  // Cutoff form
  const [showCutoffForm, setShowCutoffForm] = useState(false);
  const [cutoffForm, setCutoffForm] = useState({
    cutoff_type: 'eau',
    start_date: '',
    end_date_estimated: '',
    floors_affected: '',
    message: '',
  });
  const [isSavingCutoff, setIsSavingCutoff] = useState(false);

  // Photo upload
  const [isUploadingPhotos, setIsUploadingPhotos] = useState(false);
  const [photoCaption, setPhotoCaption] = useState('');
  const [selectedPhoto, setSelectedPhoto] = useState<string | null>(null);

  // Report revision state
  const [revisionMessage, setRevisionMessage] = useState<string | null>(null);
  const [reportStatus, setReportStatus] = useState<string | null>(null);


  const fetchData = useCallback(async () => {
    setIsLoading(true);

    // Fetch intervention
    const { data: ivData } = await supabase
      .from('interventions')
      .select('id, title, description, address, date_planned, date_end, status, client_info, keys_info, regie:regies(id, name, phone, email_contact)')
      .eq('id', interventionId)
      .single();

    if (!ivData) {
      toast.error('Chantier introuvable');
      router.push('/technician/chantier');
      return;
    }
    setIntervention(ivData as ChantierIntervention);

    // Fetch chantier_details (may not exist yet)
    try {
      const { data: detailsData } = await supabase
        .from('chantier_details')
        .select('*')
        .eq('intervention_id', interventionId)
        .maybeSingle();
      if (detailsData) {
        setDetails(detailsData as ChantierDetails);
      }
    } catch {
      // Table may not exist yet
    }

    // Fetch messages
    try {
      const { data: msgData } = await supabase
        .from('chantier_messages')
        .select('id, message, photos, created_at, author:users!chantier_messages_author_id_fkey(id, first_name, last_name)')
        .eq('intervention_id', interventionId)
        .order('created_at', { ascending: false });
      if (msgData) setMessages(msgData as ChantierMessage[]);
    } catch {
      // Table may not exist yet
    }

    // Fetch cutoff notices
    try {
      const { data: cutoffData } = await supabase
        .from('chantier_cutoff_notices')
        .select('id, cutoff_type, start_date, end_date_estimated, floors_affected, message, created_at')
        .eq('intervention_id', interventionId)
        .order('created_at', { ascending: false });
      if (cutoffData) setCutoffs(cutoffData as CutoffNotice[]);
    } catch {
      // Table may not exist yet
    }

    // Fetch intervention reminders
    try {
      const { data: reminderData } = await supabase
        .from('intervention_reminders')
        .select('id, reminder_date, message, completed, reminder_type, created_at')
        .eq('intervention_id', interventionId)
        .order('reminder_date', { ascending: true });
      if (reminderData) setReminders(reminderData as InterventionReminder[]);
    } catch {
      // Table may not exist yet
    }

    // Fetch chantier photos
    try {
      const { data: photoData } = await supabase
        .from('chantier_photos')
        .select('id, photo_url, caption, created_at, user:users!chantier_photos_user_id_fkey(id, first_name, last_name)')
        .eq('intervention_id', interventionId)
        .order('created_at', { ascending: false });
      if (photoData) setChantierPhotos(photoData as ChantierPhoto[]);
    } catch {
      // Table may not exist yet
    }

    // Fetch report status (check for revision requested)
    try {
      const { data: reportData } = await supabase
        .from('reports')
        .select('status, revision_requested, revision_message')
        .eq('intervention_id', interventionId)
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle<Pick<Report, 'status' | 'revision_requested' | 'revision_message'>>();
      if (reportData) {
        setReportStatus(reportData.status);
        if (reportData.revision_requested && reportData.revision_message) {
          setRevisionMessage(reportData.revision_message);
        }
      }
    } catch {
      // Table may not exist yet
    }

    setIsLoading(false);
  }, [interventionId, router, supabase]);

  useEffect(() => { fetchData(); }, [fetchData]);

  // Realtime: listen for changes on this chantier
  useEffect(() => {
    const channel = supabase
      .channel('chantier-detail-' + interventionId)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'interventions', filter: 'id=eq.' + interventionId }, () => {
        fetchData();
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'chantier_messages', filter: 'intervention_id=eq.' + interventionId }, () => {
        fetchData();
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'chantier_photos', filter: 'intervention_id=eq.' + interventionId }, () => {
        fetchData();
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'chantier_cutoff_notices', filter: 'intervention_id=eq.' + interventionId }, () => {
        fetchData();
      })
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [interventionId, supabase, fetchData]);

  const handleSendMessage = async () => {
    if (!newMessage.trim()) return;
    setIsSendingMessage(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error('Non authentifié');

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { error } = await (supabase as any)
        .from('chantier_messages')
        .insert({
          intervention_id: interventionId,
          author_id: user.id,
          message: newMessage.trim(),
          photos: [],
        });

      if (error) throw error;

      // Notify admins
      const { data: admins, error: adminsErr } = await supabase.from('users').select('id').in('role', ['admin', 'secretary']).returns<Pick<UserRow, 'id'>[]>();
      if (adminsErr) console.error('Failed to fetch admins for notification:', adminsErr);
      if (admins && admins.length > 0) {
        const notifs = admins.filter(a => a.id !== user.id).map(a => ({
          recipient_id: a.id,
          sender_id: user.id,
          title: 'Message chantier',
          message: `${intervention?.title}: ${newMessage.trim().substring(0, 100)}`,
          type: 'chantier_update',
          reference_id: interventionId,
          reference_type: 'chantier',
        }));
        if (notifs.length > 0) {
          const { error: notifError } = await (supabase as any).from('notifications').insert(notifs);
          if (notifError) console.error('Notification insert error:', notifError);
          notifs.forEach(n => sendPush({ recipient_id: n.recipient_id, title: n.title, message: n.message, url: `/chantiers/${interventionId}` }));
        }
      }

      toast.success('Message envoyé');
      setNewMessage('');
      fetchData();
    } catch (error) {
      console.error('Error sending message:', error);
      toast.error('Erreur lors de l\'envoi du message');
    } finally {
      setIsSendingMessage(false);
    }
  };

  const handleSaveCutoff = async () => {
    if (!cutoffForm.start_date) { toast.error('Date de début requise'); return; }
    setIsSavingCutoff(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error('Non authentifié');

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { error } = await (supabase as any)
        .from('chantier_cutoff_notices')
        .insert({
          intervention_id: interventionId,
          cutoff_type: cutoffForm.cutoff_type,
          start_date: new Date(cutoffForm.start_date).toISOString(),
          end_date_estimated: cutoffForm.end_date_estimated ? new Date(cutoffForm.end_date_estimated).toISOString() : null,
          floors_affected: cutoffForm.floors_affected || null,
          message: cutoffForm.message || null,
          created_by: user.id,
        });

      if (error) throw error;

      // Notify admins
      const { data: admins2, error: adminsErr2 } = await supabase.from('users').select('id').in('role', ['admin', 'secretary']).returns<Pick<UserRow, 'id'>[]>();
      if (adminsErr2) console.error('Failed to fetch admins for notification:', adminsErr2);
      if (admins2 && admins2.length > 0) {
        const notifs = admins2.filter(a => a.id !== user.id).map(a => ({
          recipient_id: a.id,
          sender_id: user.id,
          title: 'Avis de coupure',
          message: `${intervention?.title}: coupure ${cutoffForm.cutoff_type}`,
          type: 'chantier_update',
          reference_id: interventionId,
          reference_type: 'chantier',
        }));
        if (notifs.length > 0) {
          const { error: notifError } = await (supabase as any).from('notifications').insert(notifs);
          if (notifError) console.error('Notification insert error:', notifError);
          notifs.forEach(n => sendPush({ recipient_id: n.recipient_id, title: n.title, message: n.message, url: `/chantiers/${interventionId}` }));
        }
      }

      toast.success('Avis de coupure enregistré');
      setShowCutoffForm(false);
      setCutoffForm({ cutoff_type: 'eau', start_date: '', end_date_estimated: '', floors_affected: '', message: '' });
      fetchData();
    } catch (error) {
      console.error('Error saving cutoff:', error);
      toast.error('Erreur lors de l\'enregistrement');
    } finally {
      setIsSavingCutoff(false);
    }
  };

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    setIsUploadingPhotos(true);

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error('Non authentifié');

      for (let i = 0; i < files.length; i++) {
        const file = await normalizeImage(files[i]);
        const timestamp = Date.now();
        const path = `chantier-photos/${interventionId}/${timestamp}_${i}.jpg`;

        const { error: uploadError } = await supabase.storage
          .from('photos')
          .upload(path, file, { upsert: true });

        if (uploadError) {
          console.error('Upload error:', uploadError);
          throw new Error(`Échec upload: ${uploadError.message}`);
        }

        const { data: urlData } = supabase.storage.from('photos').getPublicUrl(path);

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { error: insertError } = await (supabase as any).from('chantier_photos').insert({
          intervention_id: interventionId,
          user_id: user.id,
          photo_url: urlData.publicUrl,
          caption: photoCaption || null,
        });

        if (insertError) {
          console.error('Insert error:', insertError);
          throw new Error(`Échec enregistrement: ${insertError.message}`);
        }
      }

      // Notify admins (don't break flow on failure)
      const { data: admins3, error: adminsErr3 } = await supabase.from('users').select('id').in('role', ['admin', 'secretary']).returns<Pick<UserRow, 'id'>[]>();
      if (adminsErr3) console.error('Failed to fetch admins for notification:', adminsErr3);
      if (admins3 && admins3.length > 0) {
        const notifs3 = admins3.filter(a => a.id !== user.id).map(a => ({
          recipient_id: a.id,
          sender_id: user.id,
          title: 'Nouvelles photos chantier',
          message: `${intervention?.title}: ${files.length} photo${files.length > 1 ? 's' : ''} ajoutée${files.length > 1 ? 's' : ''}`,
          type: 'chantier_update',
          reference_id: interventionId,
          reference_type: 'chantier',
        }));
        if (notifs3.length > 0) {
          const { error: notifError3 } = await (supabase as any).from('notifications').insert(notifs3);
          if (notifError3) console.error('Photo notification insert error:', notifError3);
          notifs3.forEach(n => sendPush({ recipient_id: n.recipient_id, title: n.title, message: n.message, url: `/chantiers/${interventionId}` }));
        }
      }

      toast.success(`${files.length} photo${files.length > 1 ? 's' : ''} uploadée${files.length > 1 ? 's' : ''}`);
      setPhotoCaption('');
      fetchData();
    } catch (error) {
      console.error('Error uploading photos:', error);
      toast.error((error as Error).message || 'Erreur lors de l\'upload');
    } finally {
      setIsUploadingPhotos(false);
      // Reset the file input
      e.target.value = '';
    }
  };

  const getCutoffIcon = (type: string) => {
    switch (type) {
      case 'eau': return <Droplets className="w-5 h-5 text-blue-500" />;
      case 'electricite': return <Zap className="w-5 h-5 text-yellow-500" />;
      case 'gaz': return <Flame className="w-5 h-5 text-orange-500" />;
      default: return <AlertTriangle className="w-5 h-5 text-red-500" />;
    }
  };

  const getCutoffLabel = (type: string) => {
    switch (type) {
      case 'eau': return 'Coupure d\'eau';
      case 'electricite': return 'Coupure électricité';
      case 'gaz': return 'Coupure gaz';
      default: return 'Coupure';
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <Loader2 className="w-8 h-8 text-blue-600 animate-spin" />
      </div>
    );
  }

  if (!intervention) return null;

  const inputClass = 'w-full h-10 px-3 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white';

  return (
    <div className="px-4 py-6 max-w-lg mx-auto">
      {/* Header */}
      <div className="flex items-center gap-3 mb-4">
        <Link href="/technician/chantier" className="p-2 hover:bg-gray-100 rounded-lg">
          <ChevronLeft className="w-5 h-5 text-gray-500" />
        </Link>
        <div className="flex-1 min-w-0">
          <h1 className="text-lg font-bold text-gray-900 truncate">{intervention.title}</h1>
          <div className="flex items-center gap-1.5 text-sm text-gray-500">
            <MapPin className="w-3.5 h-3.5" />
            <span className="truncate">{intervention.address}</span>
          </div>
        </div>
      </div>

      {/* Revision requested banner */}
      {revisionMessage && (reportStatus === 'rejected' || reportStatus === 'revision_requested') && (
        <div className="bg-orange-50 border border-orange-300 rounded-2xl p-4 mb-4 shadow-sm">
          <div className="flex items-start gap-3">
            <AlertTriangle className="w-5 h-5 text-orange-600 flex-shrink-0 mt-0.5" />
            <div className="flex-1">
              <p className="text-sm font-semibold text-orange-800">Révision demandée</p>
              <p className="text-sm text-orange-700 mt-1">{revisionMessage}</p>
              <Link
                href={`/technician/report/${intervention.id}`}
                className="inline-flex items-center gap-1.5 mt-3 px-4 py-2 text-sm font-medium text-white bg-orange-600 rounded-lg hover:bg-orange-700 transition-colors"
              >
                <FileText className="w-4 h-4" />
                Modifier et resoumettre le rapport
              </Link>
            </div>
          </div>
        </div>
      )}

      {/* Progress bar */}
      {intervention && (
        (() => {
          const progress = computeChantierProgress(intervention.date_planned, intervention.date_end);
          return (
            <div className="bg-white rounded-2xl border border-gray-200 p-4 mb-4 shadow-sm">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-medium text-gray-700">Progression</span>
                <span className="text-sm font-bold text-blue-600">{progress}%</span>
              </div>
              <div className="h-3 bg-gray-100 rounded-full overflow-hidden">
                <div
                  className={`h-full rounded-full transition-all duration-300 ${
                    progress >= 100 ? 'bg-emerald-500' : 'bg-gradient-to-r from-blue-500 to-blue-600'
                  }`}
                  style={{ width: `${progress}%` }}
                />
              </div>
            </div>
          );
        })()
      )}

      {/* Tabs */}
      <div className="flex items-center gap-1 bg-gray-100 rounded-xl p-1 mb-4">
        {([
          { key: 'overview' as TabType, label: 'Infos', icon: Building2 },
          { key: 'journal' as TabType, label: 'Journal', icon: MessageSquare },
          { key: 'cutoffs' as TabType, label: 'Coupures', icon: AlertTriangle },
          { key: 'photos' as TabType, label: 'Photos', icon: Camera },
        ]).map((tab) => (
          <button
            key={tab.key}
            onClick={() => setActiveTab(tab.key)}
            className={`flex-1 flex items-center justify-center gap-1.5 py-2 rounded-lg text-sm font-medium transition-all ${
              activeTab === tab.key ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500'
            }`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label}
            {tab.key === 'photos' && chantierPhotos.length > 0 && (
              <span className="px-1.5 py-0.5 text-[10px] font-semibold rounded-full bg-gray-200 text-gray-600">
                {chantierPhotos.length}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* ═══ TAB: Overview ═══ */}
      {activeTab === 'overview' && (
        <div className="space-y-4">
          {/* Dates du chantier */}
          {(intervention.date_planned || intervention.date_end) && (
            <div className="bg-white rounded-2xl border border-gray-200 p-4 shadow-sm">
              <h3 className="font-semibold text-gray-900 mb-3 flex items-center gap-2">
                <CalendarDays className="w-4 h-4 text-blue-600" />Dates du chantier
              </h3>
              <div className="grid grid-cols-2 gap-3">
                {intervention.date_planned && (
                  <div className="p-3 bg-blue-50 rounded-lg border border-blue-200">
                    <p className="text-xs font-medium text-blue-600 mb-0.5">Début</p>
                    <p className="text-sm font-semibold text-blue-900">
                      {format(new Date(intervention.date_planned), 'd MMM yyyy', { locale: fr })}
                    </p>
                  </div>
                )}
                {intervention.date_end && (
                  <div className="p-3 bg-blue-50 rounded-lg border border-blue-200">
                    <p className="text-xs font-medium text-blue-600 mb-0.5">Fin</p>
                    <p className="text-sm font-semibold text-blue-900">
                      {format(new Date(intervention.date_end), 'd MMM yyyy', { locale: fr })}
                    </p>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* Contacts */}
          <div className="bg-white rounded-2xl border border-gray-200 p-4 shadow-sm">
            <h3 className="font-semibold text-gray-900 mb-3 flex items-center gap-2">
              <User className="w-4 h-4 text-blue-600" />Contacts
            </h3>
            <div className="space-y-3">
              {/* Architecte */}
              {details?.architect_name && (
                <ContactRow
                  role="Architecte"
                  name={details.architect_name}
                  phone={details.architect_phone}
                  email={details.architect_email}
                />
              )}
              {/* Chef de chantier */}
              {details?.site_manager_name && (
                <ContactRow
                  role="Chef de chantier"
                  name={details.site_manager_name}
                  phone={details.site_manager_phone}
                />
              )}
              {/* Régie */}
              {intervention.regie && (
                <ContactRow
                  role="Régie"
                  name={intervention.regie.name}
                  phone={intervention.regie.phone}
                  email={intervention.regie.email_contact}
                />
              )}
              {/* Client */}
              {intervention.client_info?.name && (
                <ContactRow
                  role="Client / Propriétaire"
                  name={intervention.client_info.name}
                  phone={intervention.client_info.phone}
                />
              )}
              {!details?.architect_name && !details?.site_manager_name && !intervention.regie && !intervention.client_info?.name && (
                <p className="text-sm text-gray-400 italic">Aucun contact renseigné</p>
              )}
            </div>
          </div>

          {/* Clés & Accès */}
          <div className="bg-white rounded-2xl border border-gray-200 p-4 shadow-sm">
            <h3 className="font-semibold text-gray-900 mb-3 flex items-center gap-2">
              <Key className="w-4 h-4 text-amber-600" />Clés & Accès
