const PRIORITY_OPTIONS = [
  { value: 0, label: 'Normal' },
  { value: 1, label: 'Urgent' },
  { value: 2, label: 'Urgence absolue' },
];

export function InterventionForm({ 
  intervention, 
  onSuccess, 
  onCancel,
  onDelete 
}: InterventionFormProps) {
  const isEditMode = !!intervention;
  const [isLoading, setIsLoading] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [technicians, setTechnicians] = useState<Technician[]>([]);
  const [regies, setRegies] = useState<Regie[]>([]);

  const [formData, setFormData] = useState({
    title: intervention?.title || '',
    description: intervention?.description || '',
    address: intervention?.address || '',
    date_planned: interventionDateFields(intervention?.date_planned).date,
    time_planned: interventionDateFields(intervention?.date_planned).time,
    date_end: interventionDateFields(intervention?.date_end).date,
    estimated_duration_minutes: intervention?.estimated_duration_minutes || 60,
    priority: intervention?.priority || 0,
    technician_id: intervention?.technician_id || '',
    regie_id: intervention?.regie_id || '',
    work_order_number: intervention?.work_order_number || '',
    keys_info: intervention?.keys_info || '',
    client_name: (intervention?.client_info as { name?: string })?.name || '',
    client_phone: (intervention?.client_info as { phone?: string })?.phone || '',
    intervention_type: intervention?.intervention_type || 'depannage',
  });

  // Cutoff notice state (chantier only)
  const [cutoffEnabled, setCutoffEnabled] = useState(false);
  const [cutoffDate, setCutoffDate] = useState('');

  const isChantier = formData.intervention_type === 'chantier';

  const supabase = createClient();

  // Fetch technicians and regies on mount
  useEffect(() => {
    const fetchData = async () => {
      // Fetch technicians (users with role 'technician')
      const { data: techData } = await supabase
        .from('users')
        .select('id, first_name, last_name, email, intervention_type_preference')
        .eq('role', 'technician')
        .order('last_name');

      if (techData) {
        setTechnicians(techData);
      }

      // Fetch regies
      const { data: regieData } = await supabase
        .from('regies')
        .select('id, name')
        .eq('is_active', true)
        .order('name');

      if (regieData) {
        setRegies(regieData);
      }
    };

    fetchData();
  }, [supabase]);

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>
  ) => {
    const { name, value } = e.target;
    setFormData((prev) => {
      const updated = {
        ...prev,
        [name]: name === 'priority' || name === 'estimated_duration_minutes'
          ? parseInt(value)
          : value,
      };
      // Reset technician if type changes and current tech doesn't match
      if (name === 'intervention_type' && prev.technician_id) {
        const currentTech = technicians.find(t => t.id === prev.technician_id);
        if (currentTech?.intervention_type_preference && currentTech.intervention_type_preference !== value) {
          updated.technician_id = '';
        }
      }
      return updated;
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const dates = buildInterventionDates(formData, intervention);

      // Prepare client_info JSON
      const clientInfo: Record<string, string> = {};
      if (formData.client_name) clientInfo.name = formData.client_name;
      if (formData.client_phone) clientInfo.phone = formData.client_phone;

      const interventionData = {
        title: formData.title,
        description: formData.description || null,
        address: formData.address,
        date_planned: dates.date_planned,
        date_end: dates.date_end,
        estimated_duration_minutes: isChantier ? 480 : formData.estimated_duration_minutes,
        intervention_type: formData.intervention_type,
        status: isEditMode ? (intervention?.status || 'planifie') : 'planifie',
        priority: formData.priority,
        technician_id: formData.technician_id || null,
        regie_id: formData.regie_id || null,
        work_order_number: formData.work_order_number || null,
        keys_info: formData.keys_info || null,
        client_info: Object.keys(clientInfo).length > 0 ? clientInfo : null,
      };

      // Helper: insert a cutoff reminder + fire push notification
      const createCutoffReminder = async (interventionId: string, techId: string) => {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { error: reminderErr } = await (supabase as any).from('intervention_reminders').insert({
          intervention_id: interventionId,
          user_id: techId,
          reminder_date: cutoffDate,
          message: 'Avis de coupure d eau',
          reminder_type: 'cutoff',
        });
        if (reminderErr) {
          console.error('Cutoff reminder insert failed:', reminderErr);
          return;
        }
        sendPush({
          recipient_id: techId,
          title: 'Avis de coupure d\'eau',
          message: `${formData.title} — ${formData.address}`,
          url: isChantier ? `/technician/chantier/${interventionId}` : `/technician/report/${interventionId}`,
        });
      };

      if (isEditMode && intervention) {
        // UPDATE
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { error } = await (supabase as any)
          .from('interventions')
          .update(interventionData)
          .eq('id', intervention.id);

        if (error) {
          console.error('Supabase error:', error);
          throw new Error(error.message);
        }

        // Cutoff reminder works for both chantier and dépannage
        if (cutoffEnabled && cutoffDate) {
          const techId = formData.technician_id || intervention.technician_id;
          if (techId) await createCutoffReminder(intervention.id, techId);
        }

        toast.success('Intervention modifiée avec succès');
      } else {
        // INSERT
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { data, error } = await (supabase as any).from('interventions').insert({
          ...interventionData,
          source_type: 'manual',
        }).select('id');

        if (error) {
          console.error('Supabase error:', error);
          throw new Error(error.message);
        }

        // Cutoff reminder works for both chantier and dépannage
        if (cutoffEnabled && cutoffDate && data?.[0]?.id && formData.technician_id) {
          await createCutoffReminder(data[0].id, formData.technician_id);
        }

        toast.success('Intervention créée avec succès');
      }

      onSuccess();
    } catch (error) {
      console.error('Error saving intervention:', error);
      toast.error(error instanceof Error ? error.message : 'Impossible d’enregistrer l’intervention.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleDelete = async () => {
    if (!intervention) return;

    setIsDeleting(true);
    try {
      // Option 1: Actually delete
      // const { error } = await supabase
      //   .from('interventions')
      //   .delete()
      //   .eq('id', intervention.id);

      // Option 2: Set status to 'annule' (soft delete)
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { error } = await (supabase as any)
        .from('interventions')
        .update({ status: 'annule' })
        .eq('id', intervention.id);

      if (error) {
        throw new Error(error.message);
      }

      toast.success('Intervention annulée');
      onDelete?.();
      onSuccess();
    } catch (error) {
      console.error('Error deleting intervention:', error);
      toast.error('Erreur lors de l\'annulation');
    } finally {
      setIsDeleting(false);
      setShowDeleteConfirm(false);
    }
  };

  const getTechnicianDisplayName = (tech: Technician) => {
    if (tech.first_name && tech.last_name) {
      return `${tech.first_name} ${tech.last_name}`;
    }
    if (tech.first_name) return tech.first_name;
    if (tech.last_name) return tech.last_name;
    return tech.email;
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-5">
      {intervention?.id && intervention.intervention_type === 'chantier' && <ChantierDocuments key={intervention.id} interventionId={intervention.id} />}
      {/* Titre */}
      <div>
        <label htmlFor="title" className="block text-sm font-medium text-gray-700 mb-1.5">
          Titre <span className="text-red-500">*</span>
        </label>
        <input
          type="text"
          id="title"
          name="title"
          required
          value={formData.title}
          onChange={handleChange}
          placeholder="Ex: Fuite robinet cuisine"
          className="w-full h-10 px-3 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
        />
      </div>

      {/* Description */}
      <div>
        <label htmlFor="description" className="block text-sm font-medium text-gray-700 mb-1.5">
          Description
        </label>
        <textarea
          id="description"
          name="description"
          rows={3}
          value={formData.description}
          onChange={handleChange}
          placeholder="Détails de l'intervention..."
          className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none"
        />
      </div>

      {/* Adresse */}
      <div>
        <label htmlFor="address" className="block text-sm font-medium text-gray-700 mb-1.5">
          Adresse <span className="text-red-500">*</span>
        </label>
        <input
          type="text"
          id="address"
          name="address"
          required
          value={formData.address}
          onChange={handleChange}
          placeholder="Rue, NPA Ville"
          className="w-full h-10 px-3 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
        />
      </div>

      {/* Technicien assigné */}
      <div>
        <label htmlFor="technician_id" className="block text-sm font-medium text-gray-700 mb-1.5">
          Technicien assigné
        </label>
        <select
          id="technician_id"
          name="technician_id"
