      )}

      {/* Durée estimée (dépannage only) */}
      {!isChantier && (
        <div>
          <label htmlFor="estimated_duration_minutes" className="block text-sm font-medium text-gray-700 mb-1.5">
            Durée estimée (min)
          </label>
          <input type="number" id="estimated_duration_minutes" name="estimated_duration_minutes" min="15" step="15" value={formData.estimated_duration_minutes} onChange={handleChange} className="w-full h-10 px-3 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent" />
        </div>
      )}

      {/* Avis de coupure (chantier ET dépannage) */}
      <div className="pt-4 border-t border-gray-100">
        <label className="flex items-center gap-3 cursor-pointer">
          <input
            type="checkbox"
            checked={cutoffEnabled}
            onChange={(e) => setCutoffEnabled(e.target.checked)}
            className="w-4 h-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
          />
          <span className="flex items-center gap-1.5 text-sm font-medium text-gray-700">
            <Droplets className="w-4 h-4 text-blue-500" />
            Coupure d&apos;eau prévue
          </span>
        </label>
        {cutoffEnabled && (
          <div className="mt-3 ml-7">
            <label htmlFor="cutoff_date" className="block text-sm text-gray-600 mb-1.5">
              Date de la coupure
            </label>
            <input
              type="date"
              id="cutoff_date"
              value={cutoffDate}
              onChange={(e) => setCutoffDate(e.target.value)}
              className="w-full h-10 px-3 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />
          </div>
        )}
      </div>

      {/* Priorité */}
      <div>
        <label htmlFor="priority" className="block text-sm font-medium text-gray-700 mb-1.5">
          Priorité
        </label>
        <select
          id="priority"
          name="priority"
          value={formData.priority}
          onChange={handleChange}
          className="w-full h-10 px-3 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white"
        >
          {PRIORITY_OPTIONS.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
      </div>

      {/* Informations client */}
      <div className="pt-4 border-t border-gray-100">
        <p className="text-sm font-medium text-gray-700 mb-3">Informations client</p>
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label htmlFor="client_name" className="block text-sm text-gray-600 mb-1.5">
              Nom du client
            </label>
            <input
              type="text"
              id="client_name"
              name="client_name"
              value={formData.client_name}
              onChange={handleChange}
              placeholder="M. Dupont"
              className="w-full h-10 px-3 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />
          </div>
          <div>
            <label htmlFor="client_phone" className="block text-sm text-gray-600 mb-1.5">
              Téléphone
            </label>
            <input
              type="tel"
              id="client_phone"
              name="client_phone"
              value={formData.client_phone}
              onChange={handleChange}
              placeholder="+41 79 123 45 67"
              className="w-full h-10 px-3 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />
          </div>
        </div>
      </div>

      {/* Delete confirmation */}
      {showDeleteConfirm && (
        <div className="p-4 bg-red-50 border border-red-200 rounded-lg">
          <div className="flex items-start gap-3">
            <AlertTriangle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
            <div className="flex-1">
              <p className="text-sm font-medium text-red-800">
                Confirmer l&apos;annulation
              </p>
              <p className="text-sm text-red-600 mt-1">
                Cette intervention sera marquée comme annulée. Êtes-vous sûr ?
              </p>
              <div className="flex gap-2 mt-3">
                <button
                  type="button"
                  onClick={handleDelete}
                  disabled={isDeleting}
                  className="inline-flex items-center gap-1.5 px-3 py-1.5 text-sm font-medium text-white bg-red-600 hover:bg-red-700 rounded-lg transition-colors disabled:opacity-50"
                >
                  {isDeleting && <Loader2 className="w-3 h-3 animate-spin" />}
                  Oui, annuler
                </button>
                <button
                  type="button"
                  onClick={() => setShowDeleteConfirm(false)}
                  className="px-3 py-1.5 text-sm font-medium text-gray-700 bg-white border border-gray-200 hover:bg-gray-50 rounded-lg transition-colors"
                >
                  Non, garder
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Actions */}
      <div className="flex items-center justify-between pt-4 border-t border-gray-100">
        {/* Delete button (only in edit mode) */}
        <div>
          {isEditMode && !showDeleteConfirm && (
            <button
              type="button"
              onClick={() => setShowDeleteConfirm(true)}
              className="inline-flex items-center gap-1.5 px-3 py-2 text-sm font-medium text-red-600 hover:text-red-700 hover:bg-red-50 rounded-lg transition-colors"
            >
              <Trash2 className="w-4 h-4" />
              Annuler le RDV
            </button>
          )}
        </div>

        {/* Save/Cancel buttons */}
        <div className="flex items-center gap-3">
          <button
            type="button"
            onClick={onCancel}
            disabled={isLoading}
            className="px-4 py-2.5 text-sm font-medium text-gray-700 bg-white border border-gray-200 hover:bg-gray-50 rounded-lg transition-colors disabled:opacity-50"
          >
            Fermer
          </button>
          <button
            type="submit"
            disabled={isLoading || isDeleting}
            className="inline-flex items-center gap-2 px-4 py-2.5 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-lg transition-colors shadow-sm disabled:opacity-50"
          >
            {isLoading && <Loader2 className="w-4 h-4 animate-spin" />}
            {isLoading ? 'Enregistrement...' : isEditMode ? 'Modifier' : 'Créer'}
          </button>
        </div>
      </div>
    </form>
  );
}

'use client';

import { useState, useRef } from 'react';
import { useRouter } from 'next/navigation';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { uploadReportPhotos, type ReportPhoto } from '@/lib/report-photos';
import { PhotoUploader } from './PhotoUploader';
import { SignatureCanvas } from './SignatureCanvas';
import { GoogleReviewsQR } from './GoogleReviewsQR';
import { cn } from '@/lib/utils';
import type { Intervention, Report, Product } from '@/types/database';
import {
  Save,
  Send,
  XCircle,
  Loader2,
  AlertTriangle,
  Package,
} from 'lucide-react';

interface ReportFormProps {
  intervention: Intervention;
  existingReport: Report | null;
  products: Product[];
  technicianId: string;
}

export function ReportForm({
  intervention,
  existingReport,
  products,
  technicianId,
}: ReportFormProps) {
  const router = useRouter();
  const supabase = createClient();
  const isChantier = (intervention as Record<string, unknown>).intervention_type === 'chantier';

  // Parse existing photos into before/after categories
  const parseExistingPhotos = () => {
    const existingPhotos = (existingReport?.photos as unknown as (string | { url: string; caption?: string; category?: string })[]) || [];
    const before: ReportPhoto[] = [];
    const after: ReportPhoto[] = [];
    const uncategorized: ReportPhoto[] = [];

    existingPhotos.forEach((photo) => {
      if (typeof photo === 'string') {
        uncategorized.push({ url: photo });
      } else if (photo.category === 'before') {
        before.push({ url: photo.url, caption: photo.caption });
      } else if (photo.category === 'after') {
        after.push({ url: photo.url, caption: photo.caption });
      } else {
        uncategorized.push({ url: photo.url, caption: photo.caption });
      }
    });

    if (before.length === 0 && after.length === 0 && uncategorized.length > 0) {
      return { before: uncategorized, after: [] };
    }

    return { before: [...before, ...uncategorized], after };
  };

  const parsedPhotos = parseExistingPhotos();

  // =============================================
  // FORM STATE
  // =============================================

  const [textContent, setTextContent] = useState(existingReport?.text_content || '');
  const [photosBefore, setPhotosBefore] = useState<ReportPhoto[]>(parsedPhotos.before);
  const [photosAfter, setPhotosAfter] = useState<ReportPhoto[]>(parsedPhotos.after);
  const [processingBefore, setProcessingBefore] = useState(false);
  const [processingAfter, setProcessingAfter] = useState(false);
  const saveLock = useRef(false);
  const [isBillable, setIsBillable] = useState(existingReport?.is_billable ?? true);
  const [billableReason, setBillableReason] = useState(existingReport?.billable_reason || '');
  const [workDuration, setWorkDuration] = useState(existingReport?.work_duration_minutes || 60);
  const [isCompleted, setIsCompleted] = useState(true);

  // Fournitures texte libre (sans prix)
  const [suppliesText, setSuppliesText] = useState(
    (existingReport as unknown as { supplies_text?: string })?.supplies_text || ''
  );

  // Signature client
  const [clientSignature, setClientSignature] = useState<string | null>(
    (existingReport as unknown as { client_signature?: string })?.client_signature || null
  );

  const [revisionActive, setRevisionActive] = useState(Boolean(existingReport?.revision_requested));
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [submitProgress, setSubmitProgress] = useState<string | null>(null);

  // =============================================
  // HANDLERS
  // =============================================

  const handlePhotosBeforeChange = (newPhotos: ReportPhoto[]) => {
    setPhotosBefore(newPhotos);
  };

  const handlePhotosAfterChange = (newPhotos: ReportPhoto[]) => {
    setPhotosAfter(newPhotos);
  };

  const handleSignatureChange = (dataUrl: string | null) => {
    setClientSignature(dataUrl);
  };

  // Total photos count
  const totalPhotos = photosBefore.length + photosAfter.length;

  // =============================================
  // UPLOAD HELPERS
  // =============================================

  const uploadPhotos = async () => {
    const bucket = {
      upload: (...args: Parameters<ReturnType<typeof supabase.storage.from>['upload']>) => supabase.storage.from('photos').upload(...args),
      download: (path: string) => supabase.storage.from('photos').download(path),
    };
    const before = await uploadReportPhotos(photosBefore, 'before', technicianId, intervention.id, bucket, setPhotosBefore);
    const after = await uploadReportPhotos(photosAfter, 'after', technicianId, intervention.id, bucket, setPhotosAfter);
    if (before.failed + after.failed) throw new Error(`${before.failed + after.failed} photo(s) restent à envoyer. Les autres sont conservées pour la reprise ; le rapport n’a pas encore été enregistré.`);
    return [...before.photos, ...after.photos];
  };

  const uploadSignature = async (dataUrl: string): Promise<string> => {
    const response = await fetch(dataUrl);
    const blob = await response.blob();

    const fileName = `signatures/intervention-${intervention.id}-${Date.now()}.png`;

    const { error: uploadError } = await supabase.storage
      .from('photos')
      .upload(fileName, blob, {
        cacheControl: '3600',
        upsert: false,
        contentType: 'image/png',
      });

    if (uploadError) {
      console.error('[SIGNATURE UPLOAD ERROR]', uploadError);
      throw new Error(`Échec upload signature: ${uploadError.message}`);
    }

    const { data: { publicUrl } } = supabase.storage
      .from('photos')
      .getPublicUrl(fileName);

    return publicUrl;
  };

  // =============================================
  // BUILD REPORT DATA
  // =============================================

  const buildReportData = (allPhotos: { url: string; category: string }[], signatureUrl: string | null, status: 'draft' | 'submitted') => ({
    intervention_id: intervention.id,
    technician_id: technicianId,
    text_content: textContent || null,
    vocal_url: null,
    vocal_transcription: null,
    photos: allPhotos.length > 0 ? allPhotos : [],
    checklist: [],
    is_billable: isBillable,
    billable_reason: !isBillable ? billableReason : null,
    work_duration_minutes: isChantier ? null : workDuration,
    materials_used: [],
    supplies_text: suppliesText || null,
    client_signature: signatureUrl,
    is_completed: isCompleted,
    status,
    // Resolve the request, retaining the last feedback for consultation.
    ...(status === 'submitted' ? { revision_requested: false } : {}),
  });

  // =============================================
  // SAVE DRAFT
  // =============================================

  const handleSaveDraft = async () => {
    if (saveLock.current || processingBefore || processingAfter) return;
    saveLock.current = true;
    setIsSaving(true);
    try {
      const allPhotos = await uploadPhotos();

      let signatureUrl = null;
      if (clientSignature && clientSignature.startsWith('data:')) {
        signatureUrl = await uploadSignature(clientSignature);
      } else if (clientSignature) {
        signatureUrl = clientSignature;
      }

      const reportData = buildReportData(allPhotos, signatureUrl, 'draft');

      // Determine the report ID to update
      let reportId = existingReport?.id;

      if (!reportId) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { data: foundReport, error: lookupError } = await (supabase as any)
          .from('reports')
          .select('id')
          .eq('intervention_id', intervention.id)
          .eq('technician_id', technicianId)
          .order('created_at', { ascending: false })
          .limit(1)
          .maybeSingle();
        if (lookupError) throw new Error("Impossible de vérifier le rapport existant. Réessayez.");
        if (foundReport) reportId = foundReport.id;
      }

      if (reportId) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { data, error } = await (supabase as any)
          .from('reports')
          .update(reportData)
          .eq('id', reportId)
          .select();
        if (error) throw error;
        if (!data || data.length === 0) throw new Error('Mise à jour échouée (0 lignes)');
      } else {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { data, error } = await (supabase as any).from('reports').insert(reportData).select();
        if (error || !data?.length) throw new Error('Enregistrement du rapport non confirmé.');
      }

      setPhotosBefore(allPhotos.filter(p => p.category === 'before'));
      setPhotosAfter(allPhotos.filter(p => p.category === 'after'));
      toast.success('Brouillon sauvegardé');
    } catch (error) {

      const message = error instanceof Error ? error.message : String(error);
      toast.error(`Erreur sauvegarde: ${message}`);
    } finally {
      saveLock.current = false;
      setIsSaving(false);
    }
  };

  // =============================================
  // SUBMIT
  // =============================================

  const handleSubmit = async () => {
    if (saveLock.current || processingBefore || processingAfter) return;
    if (!textContent) {
      toast.error('Veuillez ajouter une description de l\'intervention');
      return;
    }

    saveLock.current = true;
    setIsSubmitting(true);
    setSubmitProgress('Préparation du rapport...');

    try {
      // Upload photos
      const allLocalPhotos = [
        ...photosBefore.filter(p => p.isLocal && p.file),
        ...photosAfter.filter(p => p.isLocal && p.file),
      ];

      if (allLocalPhotos.length > 0) {
        setSubmitProgress(`Upload de ${allLocalPhotos.length} photo(s)...`);
      }

      const allPhotos = await uploadPhotos();



      // Upload signature
      let signatureUrl = null;
      if (clientSignature) {
        setSubmitProgress('Upload de la signature...');
        if (clientSignature.startsWith('data:')) {
          signatureUrl = await uploadSignature(clientSignature);
        } else {
          signatureUrl = clientSignature;
        }
      }

      // Save report
      setSubmitProgress('Sauvegarde du rapport...');
      const reportData = buildReportData(allPhotos, signatureUrl, 'submitted');

      // Determine the report ID to update: use existingReport prop,
      // or look up directly if the prop was null (e.g. RLS/query issue)
      let reportId = existingReport?.id;

      if (!reportId) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { data: foundReport, error: lookupError } = await (supabase as any)
          .from('reports')
          .select('id')
          .eq('intervention_id', intervention.id)
          .eq('technician_id', technicianId)
          .order('created_at', { ascending: false })
          .limit(1)
          .maybeSingle();

        if (lookupError) throw new Error("Impossible de vérifier le rapport existant. Réessayez.");
        if (foundReport) {
          reportId = foundReport.id;
        }
      }

      if (reportId) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { data: updatedData, error } = await (supabase as any)
          .from('reports')
          .update(reportData)
          .eq('id', reportId)
          .select();

        if (error) throw error;
        if (!updatedData || updatedData.length === 0) {
          throw new Error('La mise à jour du rapport a échoué (aucune ligne modifiée). Vérifiez les permissions.');
        }
      } else {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { data: insertedData, error } = await (supabase as any)
          .from('reports')
          .insert(reportData)
          .select();

        if (error) throw error;
        if (!insertedData || insertedData.length === 0) {
          throw new Error("L'insertion du rapport a échoué. Vérifiez les permissions.");
        }
      }

      setPhotosBefore(allPhotos.filter(p => p.category === 'before'));
      setPhotosAfter(allPhotos.filter(p => p.category === 'after'));
      setRevisionActive(false);

      // Update intervention status
      setSubmitProgress("Mise à jour de l'intervention...");
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { data: intUpdateData, error: interventionError } = await (supabase as any)
        .from('interventions')
        .update({
          status: isCompleted ? 'termine' : 'en_cours',
          date_completed: isCompleted ? new Date().toISOString() : null,
        })
        .eq('id', intervention.id)
        .select();

      if (interventionError) {
        toast.warning('Rapport sauvegardé mais statut non mis à jour');
      }

      setSubmitProgress('Terminé!');
      toast.success('Rapport soumis avec succès !');

      setTimeout(() => {
        router.push('/technician/today');
        router.refresh();
      }, 500);
    } catch (error) {

      const message = error instanceof Error ? error.message : String(error);
      toast.error(`Erreur: ${message}`);
    } finally {
      saveLock.current = false;
      setIsSubmitting(false);
      setSubmitProgress(null);
    }
  };

  // =============================================
  // RENDER
  // =============================================

  return (
    <div className="space-y-6 pb-32">
      {existingReport?.revision_message && (
        <section aria-label="Retour du secrétariat" className={cn('rounded-xl border p-4', revisionActive ? 'border-amber-300 bg-amber-50' : 'border-gray-200 bg-gray-50')}>
          <h2 className="font-semibold">{revisionActive ? "Retour du secrétariat — correction demandée" : "Dernier commentaire du secrétariat (historique)"}</h2>
          <p className="mt-2 whitespace-pre-wrap break-words text-sm text-amber-900">{existingReport.revision_message}</p>
        </section>
      )}
      {/* Progress summary */}
      <div className="bg-white rounded-xl border border-gray-200 p-4">
        <h2 className="font-semibold text-gray-900 mb-3">Résumé</h2>
        <div className={cn('grid gap-3', isChantier ? 'grid-cols-2' : 'grid-cols-3')}>
          <div className="text-center p-2 bg-blue-50 rounded-lg">
            <p className="text-lg font-bold text-blue-700">{totalPhotos}</p>
            <p className="text-xs text-blue-600">Photo{totalPhotos > 1 ? 's' : ''}</p>
          </div>
          {!isChantier && (
            <div className="text-center p-2 bg-amber-50 rounded-lg">
              <p className="text-lg font-bold text-amber-700">{workDuration}</p>
              <p className="text-xs text-amber-600">Minutes</p>
            </div>
          )}
          <div className="text-center p-2 bg-emerald-50 rounded-lg">
            <p className="text-lg font-bold text-emerald-700">{isCompleted ? 'Oui' : 'Non'}</p>
            <p className="text-xs text-emerald-600">Terminée</p>
          </div>
        </div>
      </div>

      {/* ===== TERMINÉE OUI / NON ===== */}
      <div className="bg-white rounded-xl border border-gray-200 p-4">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="font-semibold text-gray-900">✅ Intervention terminée ?</h2>
            <p className="text-sm text-gray-500">L&apos;intervention est-elle complètement terminée ?</p>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setIsCompleted(true)}
              className={cn(
                'px-4 py-2 rounded-lg text-sm font-medium transition-all',
                isCompleted
                  ? 'bg-emerald-600 text-white shadow-sm'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              )}
            >
              Oui
            </button>
            <button
              onClick={() => setIsCompleted(false)}
              className={cn(
                'px-4 py-2 rounded-lg text-sm font-medium transition-all',
                !isCompleted
                  ? 'bg-amber-500 text-white shadow-sm'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              )}
            >
              Non
            </button>
          </div>
        </div>
        {!isCompleted && (
          <div className="mt-3 p-3 bg-amber-50 border border-amber-200 rounded-lg">
            <p className="text-sm text-amber-700">
              ⚠️ L&apos;intervention restera &quot;en cours&quot;. Vous pourrez revenir compléter le rapport plus tard.
            </p>
          </div>
        )}
      </div>

      {/* ===== DESCRIPTION DE L'INTERVENTION ===== */}
      <div className="bg-white rounded-xl border border-gray-200 p-4">
        <h2 className="font-semibold text-gray-900 mb-3">
          ✏️ Description de l&apos;intervention
        </h2>
        <p className="text-sm text-gray-500 mb-3">
          Décrivez le travail réalisé, les problèmes rencontrés, les solutions apportées...
        </p>
        <textarea
          value={textContent}
          onChange={(e) => setTextContent(e.target.value)}
          placeholder="Ex: Remplacement du robinet mural mélangeur par un mitigeur 120x220. Coupure d'eau effectuée, test fonctionnement OK..."
          className="w-full h-32 px-3 py-2 text-base border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
        />
      </div>

      {/* ===== FOURNITURES / PIÈCES (texte libre, SANS PRIX) ===== */}
      <div className="bg-white rounded-xl border border-gray-200 p-4">
        <div className="flex items-center gap-2 mb-3">
          <Package className="w-5 h-5 text-gray-700" />
          <h2 className="font-semibold text-gray-900">Fournitures</h2>
        </div>
        <p className="text-sm text-gray-500 mb-3">
          Listez les pièces et fournitures utilisées. Pas besoin de mettre les prix.
        </p>
        <textarea
          value={suppliesText}
          onChange={(e) => setSuppliesText(e.target.value)}
          placeholder="Ex: 1 robinet mural mitigeur 120x220, 2 raccords laiton 1/2, ruban teflon, joints fibre..."
          className="w-full h-24 px-3 py-2 text-base border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
        />
      </div>

      {/* ===== PHOTOS AVANT ===== */}
      <div className="bg-white rounded-xl border border-gray-200 p-4">
        <h2 className="font-semibold text-gray-900 mb-1">📷 Photos avant</h2>
        <p className="text-sm text-gray-500 mb-3">
          État initial, problème constaté à l&apos;arrivée
        </p>
        <PhotoUploader
          interventionId={intervention.id}
          photos={photosBefore}
          onPhotosChange={handlePhotosBeforeChange}
          disabled={isSaving || isSubmitting || processingBefore || processingAfter}
          onProcessingChange={setProcessingBefore}
          maxPhotos={5}
        />
      </div>

      {/* ===== PHOTOS APRÈS ===== */}
      <div className="bg-white rounded-xl border border-gray-200 p-4">
        <h2 className="font-semibold text-gray-900 mb-1">📸 Photos après</h2>
        <p className="text-sm text-gray-500 mb-3">
          Travail réalisé, résultat final
        </p>
        <PhotoUploader
          interventionId={intervention.id}
          photos={photosAfter}
          onPhotosChange={handlePhotosAfterChange}
          disabled={isSaving || isSubmitting || processingBefore || processingAfter}
          onProcessingChange={setProcessingAfter}
          maxPhotos={5}
        />
      </div>

      {/* ===== DURÉE DU TRAVAIL (masqué pour chantiers) ===== */}
      {!isChantier && (
      <div className="bg-white rounded-xl border border-gray-200 p-4">
        <h2 className="font-semibold text-gray-900 mb-3">
          ⏱️ Durée du travail
        </h2>
        <div className="flex items-center gap-3">
          <button
            onClick={() => setWorkDuration(Math.max(0, workDuration - 15))}
            className="w-12 h-12 flex items-center justify-center bg-gray-100 hover:bg-gray-200 rounded-xl text-xl font-bold transition-colors"
          >
            -
          </button>
          <div className="flex-1 text-center">
            <input
              type="number"
              value={workDuration}
              onChange={(e) => setWorkDuration(parseInt(e.target.value) || 0)}
              min={0}
              step={15}
              className="w-24 px-3 py-3 text-2xl font-bold text-center border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <p className="text-sm text-gray-500 mt-1">minutes</p>
          </div>
          <button
            onClick={() => setWorkDuration(workDuration + 15)}
            className="w-12 h-12 flex items-center justify-center bg-gray-100 hover:bg-gray-200 rounded-xl text-xl font-bold transition-colors"
          >
            +
          </button>
        </div>
        {/* Quick buttons */}
        <div className="flex gap-2 mt-3">
          {[30, 60, 90, 120].map((mins) => (
            <button
              key={mins}
              onClick={() => setWorkDuration(mins)}
              className={cn(
                'flex-1 py-2 rounded-lg text-sm font-medium transition-colors',
                workDuration === mins
                  ? 'bg-blue-600 text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              )}
            >
              {mins >= 60 ? `${mins / 60}h` : `${mins}m`}
            </button>
          ))}
        </div>
      </div>
      )}

      {/* ===== FACTURABLE ===== */}
      <div className="bg-white rounded-xl border border-gray-200 p-4">
        <div className="flex items-center justify-between mb-3">
          <div>
            <h2 className="font-semibold text-gray-900">💰 Facturable</h2>
            <p className="text-sm text-gray-500">Cette intervention sera facturée</p>
          </div>
          <button
            onClick={() => setIsBillable(!isBillable)}
            className={cn(
              'relative w-14 h-8 rounded-full transition-colors',
              isBillable ? 'bg-emerald-500' : 'bg-gray-300'
            )}
          >
            <span
              className={cn(
                'absolute top-1 w-6 h-6 bg-white rounded-full shadow transition-transform',
                isBillable ? 'left-7' : 'left-1'
              )}
            />
          </button>
        </div>

        {!isBillable && (
          <div className="p-3 bg-amber-50 border border-amber-200 rounded-xl">
            <div className="flex items-start gap-2 mb-2">
              <AlertTriangle className="w-5 h-5 text-amber-600 flex-shrink-0 mt-0.5" />
              <p className="text-sm text-amber-800 font-medium">
                Raison de la non-facturation
              </p>
            </div>
            <textarea
              value={billableReason}
              onChange={(e) => setBillableReason(e.target.value)}
              placeholder="Ex: Sous garantie, défaut de fabrication, geste commercial..."
              className="w-full h-20 px-3 py-2 text-base border border-amber-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-amber-500 resize-none bg-white"
            />
          </div>
        )}
      </div>

      {/* ===== SIGNATURE CLIENT ===== */}
      <div className="bg-white rounded-xl border border-gray-200 p-4">
        <h2 className="font-semibold text-gray-900 mb-1">✍️ Signature du client</h2>
        <p className="text-sm text-gray-500 mb-3">
          Faites signer le client directement sur l&apos;écran
        </p>
        <SignatureCanvas
          onSignatureChange={handleSignatureChange}
          existingSignature={clientSignature}
        />
      </div>

      {/* ===== QR CODE AVIS GOOGLE ===== */}
      <GoogleReviewsQR />

      {/* ===== ACTIONS FIXES EN BAS ===== */}
      <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/95 backdrop-blur-sm border-t border-gray-200 safe-area-pb z-50">
        <div className="flex gap-3 max-w-2xl mx-auto">
          <button
            onClick={handleSaveDraft}
            disabled={isSaving || isSubmitting || processingBefore || processingAfter}
            className="flex-1 flex items-center justify-center gap-2 py-4 px-4 border-2 border-gray-300 rounded-xl font-semibold text-gray-700 hover:bg-gray-50 disabled:opacity-50 active:scale-[0.98] transition-all"
          >
            {isSaving ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : (
              <Save className="w-5 h-5" />
            )}
            {isSaving ? 'Sauvegarde...' : 'Brouillon'}
          </button>
          <button
            onClick={handleSubmit}
            disabled={isSaving || isSubmitting || processingBefore || processingAfter}
            className="flex-1 flex items-center justify-center gap-2 py-4 px-4 bg-emerald-600 rounded-xl font-semibold text-white hover:bg-emerald-700 disabled:opacity-50 active:scale-[0.98] transition-all shadow-lg shadow-emerald-600/30"
          >
            {isSubmitting ? (
              <>
                <Loader2 className="w-5 h-5 animate-spin" />
                <span className="text-sm">{submitProgress || 'Envoi...'}</span>
              </>
            ) : (
              <>
                <Send className="w-5 h-5" />
                Soumettre
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
}
